  final mergedOptions = ShellExecOptions(
    cwd: options?.cwd,
    env: options?.env,
    timeout: options?.timeout,
    // gh-1455: caller cancel tokens NEVER reach job space. A job outlives
    // the call that started it (`background: true` returns immediately;
