  /// Sleep until the nearest wake source: a job settle, a timer due, the
  /// heartbeat cadence, or the ceiling — whichever lands first.
  Future<void> _sleepUntilWake(
    DateTime now,
    DateTime deadline,
    WaiterSnapshot snap,
    DateTime lastHeartbeat,
    int hbMin,
  ) async {
    final delay = nextWakeDelay(
      now: now,
      deadline: deadline,
